export class Transfers {
    /**
     * Approve transfer request
     *
     * Approve a transfer at its current stage. JOYFIT completes immediately (auto-execution) and moves the member’s contracted store; FIT365 advances to the destination store’s approval. Requires members.transfers-approve plus row-level eligibility.
     */
    public static patchCrmTransfersByIdApprove<ThrowOnError extends boolean = false>(options: Options<PatchCrmTransfersByIdApproveData, ThrowOnError>) {
        return (options.client ?? client).patch<PatchCrmTransfersByIdApproveResponses, PatchCrmTransfersByIdApproveErrors, ThrowOnError>({
            url: '/crm/transfers/{id}/approve',
            ...options,
            headers: {
                'Content-Type': 'application/json',
                ...options.headers
            }
        });
    }
    
    /**
     * Reject transfer request
     *
     * Reject a transfer at its current stage. The case closes and the applicant is notified. The optional comment is persisted as a decision record. Requires members.transfers-approve plus row-level eligibility.
     */
    public static patchCrmTransfersByIdReject<ThrowOnError extends boolean = false>(options: Options<PatchCrmTransfersByIdRejectData, ThrowOnError>) {
        return (options.client ?? client).patch<PatchCrmTransfersByIdRejectResponses, PatchCrmTransfersByIdRejectErrors, ThrowOnError>({
            url: '/crm/transfers/{id}/reject',
            ...options,
            headers: {
                'Content-Type': 'application/json',
                ...options.headers
            }
        });
    }
    
    /**
     * Get transfer request detail
     *
     * Get full detail of a single transfer request including approval history, decisions and unlock audit. Returns 404 when the row is outside the caller’s store scope, so existence is not leaked.
     */
    public static getCrmTransfersById<ThrowOnError extends boolean = false>(options: Options<GetCrmTransfersByIdData, ThrowOnError>) {
        return (options.client ?? client).get<GetCrmTransfersByIdResponses, GetCrmTransfersByIdErrors, ThrowOnError>({ url: '/crm/transfers/{id}', ...options });
    }
    
    /**
     * Manually release an auto-transfer exclusion (A-02 FR-012)
     *
     * Releases the campaign / cancellation-fee lock so an excluded JOYFIT transfer may proceed, recording who did it and why. A co-present unpaid balance is NOT released — that has no override. Requires members.transfers-unlock (System / Headquarter / Manager).
     */
    public static patchCrmTransfersByIdUnlock<ThrowOnError extends boolean = false>(options: Options<PatchCrmTransfersByIdUnlockData, ThrowOnError>) {
        return (options.client ?? client).patch<PatchCrmTransfersByIdUnlockResponses, PatchCrmTransfersByIdUnlockErrors, ThrowOnError>({
            url: '/crm/transfers/{id}/unlock',
            ...options,
            headers: {
                'Content-Type': 'application/json',
                ...options.headers
            }
        });
    }
    
    /**
     * Bulk approve eligible JOYFIT automatic transfers (A-02 FR-013)
     *
     * Approves many eligible JOYFIT transfers in one action. Every id is re-validated server-side (exists, in scope, JOYFIT, not excluded, approvable, actionable) and reported individually, so a partial success is returned rather than failing the whole batch. Requires members.transfers-bulk-approve (System / Headquarter / Manager).
     */
    public static postCrmTransfersBulkApprove<ThrowOnError extends boolean = false>(options?: Options<PostCrmTransfersBulkApproveData, ThrowOnError>) {
        return (options?.client ?? client).post<PostCrmTransfersBulkApproveResponses, PostCrmTransfersBulkApproveErrors, ThrowOnError>({
            url: '/crm/transfers/bulk-approve',
            ...options,
            headers: {
                'Content-Type': 'application/json',
                ...options?.headers
            }
        });
    }
    
    /**
     * Get transfer requests list
     *
     * Get a paginated, filterable list of transfer requests, scoped to the stores the caller can access (matching either the origin or the destination store)
     */
    public static getCrmTransfers<ThrowOnError extends boolean = false>(options?: Options<GetCrmTransfersData, ThrowOnError>) {
        return (options?.client ?? client).get<GetCrmTransfersResponses, GetCrmTransfersErrors, ThrowOnError>({ url: '/crm/transfers', ...options });
    }
}

